// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: blue; icon-glyph: football;
// NFL Desk — Prop Season board layout in a WebView.
// Private repo: Keychain.set("nflDeskGithubToken", "ghp_...")

const OWNER = "SpaceCooler94";
const REPO = "nfl-desk";
const BRANCH = "main";
const FEED_PATH = "feed/current.json";
const TOKEN_KEY = "nflDeskGithubToken";
const NAMES = {DET:"LIONS",BUF:"BILLS",CAR:"PANTHERS",ATL:"FALCONS",MIN:"VIKINGS",CHI:"BEARS",PHI:"EAGLES",TEN:"TITANS",PIT:"STEELERS",NE:"PATRIOTS",GB:"PACKERS",NYJ:"JETS",CLE:"BROWNS",TB:"BUCCANEERS",NO:"SAINTS",BAL:"RAVENS",CIN:"BENGALS",HOU:"TEXANS",JAX:"JAGUARS",DEN:"BRONCOS",LV:"RAIDERS",LAC:"CHARGERS",MIA:"DOLPHINS",SF:"49ERS",SEA:"SEAHAWKS",ARI:"CARDINALS",WSH:"COMMANDERS",DAL:"COWBOYS",IND:"COLTS",KC:"CHIEFS",NYG:"GIANTS",LAR:"RAMS"};
function feedUrl(){return "https://raw.githubusercontent.com/"+OWNER+"/"+REPO+"/"+BRANCH+"/"+FEED_PATH+"?t="+Date.now();}
function apiUrl(){return "https://api.github.com/repos/"+OWNER+"/"+REPO+"/contents/"+FEED_PATH+"?ref="+BRANCH;}
function token(){try{if(Keychain.contains(TOKEN_KEY))return Keychain.get(TOKEN_KEY);}catch(e){}return null;}
async function loadCard(){const hdrs={"User-Agent":"nfl-desk-scriptable"};const tok=token();if(tok)hdrs.Authorization="Bearer "+tok;try{const raw=new Request(feedUrl());raw.headers=hdrs;raw.timeoutInterval=20;return await raw.loadJSON();}catch(err){const req=new Request(apiUrl());req.headers=Object.assign({},hdrs,{Accept:"application/vnd.github.raw+json"});req.timeoutInterval=20;return await req.loadJSON();}}
function nameOf(ab){return NAMES[ab]||ab||"";}
function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;");}
function gamesFrom(card){const m=new Map();(card.games||[]).forEach(g=>m.set(g.id,g));(card.props||[]).forEach(p=>{if(!m.has(p.game_id))m.set(p.game_id,{id:p.game_id,away:p.team,home:p.opp,when:p.when});});return [...m.values()];}
function propsFor(card,gid){return (card.props||[]).filter(p=>p.game_id===gid).sort((a,b)=>Math.abs(b.edge||0)-Math.abs(a.edge||0));}
function yardsFor(g,team,rows){if(g.best_yards)return g.best_yards.filter(x=>x.team===team);return rows.filter(p=>p.team===team).slice(0,2).map(p=>({player:p.player,pos:p.pos,team:p.team,proj:p.proj,market:p.market_label||p.market,vs:p.note||"",tag:p.play||""}));}
function tdsFor(g,team){return (g.td_angles||[]).filter(x=>x.team===team);}
function css(){return "*{box-sizing:border-box}html,body{margin:0;background:#041028;color:#e8f0ff;font:13px/1.35 -apple-system}.wrap{max-width:980px;margin:0 auto;padding:12px 10px 36px}.top{display:flex;justify-content:space-between;color:#7fd7ff;font-size:10px;letter-spacing:.14em;font-weight:800}.hero{text-align:center;margin:6px 0 10px}.hero .k{color:#ff4fd8;font-size:11px;letter-spacing:.2em;font-weight:800}.hero h1{margin:4px 0;font-size:34px}.hero h1 .a{color:#c084fc}.hero h1 .h{color:#fb7185}.hero .d{color:#9fb4d9;font-size:12px}.board{display:grid;grid-template-columns:1fr 1.3fr 1fr;gap:6px;background:#0b1a3a;border:2px solid #2ee5ff;border-radius:10px;padding:8px;margin-bottom:10px}.imp{text-align:center}.imp .n{font-size:28px;font-weight:900}.imp.min .n{color:#d946ef}.imp.chi .n{color:#fb7185}.imp .l{font-size:10px;letter-spacing:.1em}.mid{text-align:center;border-left:1px solid #1e3a6a;border-right:1px solid #1e3a6a}.mid .ou{font-size:15px;font-weight:800;color:#7dd3fc}.mid .tag{color:#f472b6;font-weight:800;letter-spacing:.12em}.mid .sp{color:#cbd5e1;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px}.card{background:#071433;border-radius:10px;padding:8px}.card.min{border:2px solid #c026d3}.card.chi{border:2px solid #f97316}.card h2{margin:0 0 6px;font-size:12px;letter-spacing:.08em}.row{display:grid;grid-template-columns:1.4fr .7fr 1.1fr .7fr;gap:4px;align-items:center;padding:6px 2px;border-top:1px solid #1e3a6a}.pn{font-weight:800}.ps{font-size:10px;color:#93a4c3}.proj{font-size:18px;font-weight:900;text-align:center}.min .proj{color:#e879f9}.chi .proj{color:#fdba74}.vs{font-size:10px;color:#9fb4d9}.tag{font-size:10px;font-weight:800;color:#67e8f9;text-align:right}.td .row{grid-template-columns:1.5fr .8fr .8fr}.pct{font-size:22px;font-weight:900;text-align:center}.min .pct{color:#f0abfc}.chi .pct{color:#fdba74}.run{background:#071433;border:2px solid #38bdf8;border-radius:10px;padding:10px;margin-bottom:8px}.run h2{margin:0 0 6px;color:#7dd3fc;letter-spacing:.1em}.run ul{margin:0;padding-left:16px}.side{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}.call{background:#0a1b3d;border-radius:8px;padding:8px;text-align:center;border:1px solid #1e3a6a}.call b{display:block;color:#7dd3fc;letter-spacing:.1em;font-size:11px}.def{background:#071433;border-radius:10px;padding:8px}.def.min{border:2px solid #c026d3}.def.chi{border:2px solid #f97316}.rank{display:flex;justify-content:space-between}.rank .big{font-size:22px;font-weight:900}.soft{color:#fdba74}.tough{color:#67e8f9}.bar{display:grid;grid-template-columns:28px 1fr 36px;gap:6px;align-items:center;margin:3px 0;font-size:11px}.fill{height:8px;background:#334155;border-radius:4px;overflow:hidden}.fill span{display:block;height:8px}.why{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.why span{background:#0b1a3a;border:1px solid #38bdf8;border-radius:999px;padding:5px 8px;font-size:10px;font-weight:800}.foot{display:flex;justify-content:space-between;margin-top:10px;color:#7dd3fc;font-size:11px;font-weight:800}";}
function yardRow(x){return "<div class=\"row\"><div><div class=\"pn\">"+esc(x.player)+"</div><div class=\"ps\">"+esc([x.pos,x.team].filter(Boolean).join(" · "))+"</div></div><div class=\"proj\">"+esc(x.proj!=null?x.proj:"—")+"</div><div class=\"vs\">"+esc(x.vs||x.market||"")+"</div><div class=\"tag\">"+esc(x.tag||"")+"</div></div>";}
function tdRow(x){return "<div class=\"row\"><div><div class=\"pn\">"+esc(x.player)+"</div><div class=\"ps\">"+esc([x.pos,x.team].filter(Boolean).join(" · "))+"</div></div><div class=\"pct\">"+esc(x.pct!=null?x.pct+"%":"—")+"</div><div class=\"tag\">"+esc(x.market||"ANYTIME TD")+"</div></div>";}
function bars(def){if(!def||!def.by_pos)return"";const colors={RB:"#facc15",WR:"#4ade80",TE:"#f87171",QB:"#34d399"};return Object.keys(def.by_pos).map(k=>{const v=Number(def.by_pos[k]);const w=Math.min(100,Math.round((v/1.5)*100));return "<div class=\"bar\"><div>"+k+"</div><div class=\"fill\"><span style=\"width:"+w+"%;background:"+(colors[k]||"#38bdf8")+"\"></span></div><div>"+v.toFixed(2)+"</div></div>";}).join("");}
function give(def){if(!def||!def.give)return"";return def.give.map(x=>"<div class=\"row\" style=\"grid-template-columns:1fr 40px 28px\"><div class=\"ps\">"+esc(x.name)+"</div><div>"+esc(x.pct)+"</div><div class=\"tag\">"+esc(x.grade)+"</div></div>").join("");}
function boardHTML(card,g){const rows=propsFor(card,g.id);const awayY=yardsFor(g,g.away,rows);const homeY=yardsFor(g,g.home,rows);const awayTD=tdsFor(g,g.away);const homeTD=tdsFor(g,g.home);const run=(g.rundown||[]).map(t=>"<li>"+esc(t)+"</li>").join("")||"<li>"+esc(card.disclaimer||"")+"</li>";const script=g.script||(Number(g.total)>=47?"SHOOTOUT":"SCRIPT");const aDef=(g.defense&&g.defense[g.away])||null;const hDef=(g.defense&&g.defense[g.home])||null;const why=(g.why||[g.spread,"PLAYER PROPS"]).map(t=>"<span>"+esc(t)+"</span>").join("");return "<!DOCTYPE html><html><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><style>"+css()+"</style></head><body><div class=wrap><div class=top><div>NFL DESK · EVERY PROP</div><div>WEEK "+esc(card.week||"")+"</div></div><div class=hero><div class=k>SUNDAY NFL FOOTBALL</div><h1><span class=a>"+esc(g.away)+"</span> @ <span class=h>"+esc(g.home)+"</span></h1><div class=d>"+esc([g.when,g.venue].filter(Boolean).join(" · "))+"</div></div><div class=board><div class='imp min'><div class=n>"+esc(g.away_implied!=null?g.away_implied:"—")+"</div><div class=l>"+esc(g.away)+" IMPLIED</div></div><div class=mid><div class=ou>O/U "+esc(g.total!=null?g.total:"—")+"</div><div class=tag>"+esc(script)+"</div><div class=sp>"+esc(g.spread||"")+"</div></div><div class='imp chi'><div class=n>"+esc(g.home_implied!=null?g.home_implied:"—")+"</div><div class=l>"+esc(g.home)+" IMPLIED</div></div></div><div class=grid><div class='card min'><h2>BEST "+esc(g.away)+" YARDS</h2>"+awayY.map(yardRow).join("")+"</div><div class='card chi'><h2>BEST "+esc(g.home)+" YARDS</h2>"+homeY.map(yardRow).join("")+"</div><div class='card min td'><h2>TOP "+esc(g.away)+" TD ANGLES</h2>"+(awayTD.map(tdRow).join("")||"<div class=ps>No TD angles tagged</div>")+"</div><div class='card chi td'><h2>TOP "+esc(g.home)+" TD ANGLES</h2>"+(homeTD.map(tdRow).join("")||"<div class=ps>No TD angles tagged</div>")+"</div></div><div class=run><h2>GAME RUNDOWN</h2><ul>"+run+"</ul><div class=side><div class=call><b>WEATHER</b>"+esc(g.weather||"CHECK LOCAL")+"</div><div class=call><b>QB WATCH</b>"+esc(g.qb_watch||"—")+"</div></div></div><div class=grid>"+(hDef?"<div class='def chi'><h2>"+esc(g.home)+" DEFENSE</h2><div class=rank><div class=big>"+esc(hDef.td_rank||"")+"</div><div class=soft>"+esc(hDef.label||"")+" · "+esc(hDef.tds_allowed!=null?hDef.tds_allowed+" TDs/G":"")+"</div></div>"+bars(hDef)+give(hDef)+"</div>":"")+(aDef?"<div class='def min'><h2>"+esc(g.away)+" DEFENSE</h2><div class=rank><div class=big>"+esc(aDef.td_rank||"")+"</div><div class=tough>"+esc(aDef.label||"")+" · "+esc(aDef.tds_allowed!=null?aDef.tds_allowed+" TDs/G":"")+"</div></div>"+bars(aDef)+give(aDef)+"</div>":"")+"</div><div class=why>"+why+"</div><div class=foot><div>xDESK</div><div>"+esc(card.status||"")+" · RESEARCH</div></div></div></body></html>";}
async function presentBoard(card,g){const wv=new WebView();await wv.loadHTML(boardHTML(card,g));await wv.present(true);}
async function pickGame(card){const games=gamesFrom(card);const table=new UITable();table.showSeparators=true;const head=new UITableRow();head.isHeader=true;head.addText("NFL  PROP BOARDS");table.addRow(head);for(const g of games){const row=new UITableRow();row.height=54;row.dismissOnSelect=true;row.onSelect=async()=>{await presentBoard(card,g);};const t=row.addText(nameOf(g.away)+" @ "+nameOf(g.home)+"\n"+[g.when,g.spread,g.total].filter(Boolean).join(" · "));t.titleFont=Font.boldSystemFont(16);t.subtitleFont=Font.systemFont(11);table.addRow(row);}await table.present();}
function buildWidget(card){const w=new ListWidget();w.backgroundColor=new Color("#041028");w.setPadding(12,14,12,14);const g=gamesFrom(card).find(x=>String(x.when||"").indexOf("FINAL")===-1)||gamesFrom(card)[0]||{};const k=w.addText("NFL DESK  ·  WEEK "+(card.week||""));k.font=Font.boldSystemFont(10);k.textColor=new Color("#7fd7ff");const title=w.addText((g.away||"")+" @ "+(g.home||""));title.font=Font.boldSystemFont(22);title.textColor=Color.white();const mid=w.addText((g.spread||"")+"   O/U "+(g.total!=null?g.total:""));mid.font=Font.boldSystemFont(12);mid.textColor=new Color("#f472b6");w.addSpacer();const f=w.addText(String(g.away_implied||"")+"  –  "+String(g.home_implied||""));f.font=Font.boldSystemFont(16);f.textColor=new Color("#c084fc");return w;}
async function run(){let card;try{card=await loadCard();}catch(e){if(config.runsInWidget){const w=new ListWidget();w.addText("Feed failed");Script.setWidget(w);Script.complete();return;}const a=new Alert();a.title="NFL Desk feed failed";a.message=String(e);a.addAction("OK");await a.present();Script.complete();return;}if(config.runsInWidget){Script.setWidget(buildWidget(card));Script.complete();return;}await pickGame(card);Script.complete();}
await run();
